<?php
namespace App\Http\Controllers;
use App\Models\AuditLog; use App\Models\Event; use App\Models\Registration; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class EventController extends Controller {
 public function index(){ $events=Event::where('status','published')->where('ends_at','>=',now())->orderBy('starts_at')->get(); return view('events.index',compact('events')); }
 public function show(Event $event){ return view('events.detail',compact('event')); }
 public function create(Event $event){ abort_unless($event->status==='published' && $event->ends_at->isFuture(),422,'This event is not accepting registrations.'); return view('events.register',compact('event')); }
 public function store(Request $request,Event $event){ $data=$request->validate(['full_name'=>['required','string','max:120'],'email'=>['required','email','max:255'],'mobile'=>['required','regex:/^09\d{9}$/']],['mobile.regex'=>'Enter an 11-digit Philippine mobile number starting with 09.']); $email=strtolower($data['email']); try { $r=DB::transaction(function()use($event,$data,$email){ $e=Event::lockForUpdate()->findOrFail($event->id); if($e->status!=='published'||$e->ends_at->isPast()) abort(422,'This event is not accepting registrations.'); if(Registration::where('event_id',$e->id)->where('email',$email)->whereIn('status',['confirmed','checked_in','waitlisted'])->exists()) abort(422,'This email already has an active registration for this event.'); $confirmed=Registration::where('event_id',$e->id)->whereIn('status',['confirmed','checked_in'])->count(); $status=$confirmed>=$e->capacity?'waitlisted':'confirmed'; $position=$status==='waitlisted'?(Registration::where('event_id',$e->id)->where('status','waitlisted')->max('waitlist_position')+1):null; do{$code='EVT-'.strtoupper(Str::random(12));}while(Registration::where('ticket_code',$code)->exists()); return Registration::create(array_merge($data,['email'=>$email,'event_id'=>$e->id,'ticket_code'=>$code,'qr_token'=>Str::random(48),'status'=>$status,'waitlist_position'=>$position,'registered_at'=>now()])); }); } catch(\Symfony\Component\HttpKernel\Exception\HttpException $x){ return back()->withInput()->withErrors(['email'=>$x->getMessage()]); } $message=$r->status==='waitlisted'?"The event is full. You are #{$r->waitlist_position} on the waitlist.":'Registration complete — your ticket is ready.'; return redirect()->route('tickets.show',$r->ticket_code)->with('success',$message); }
 public function ticket(string $code){ $registration=Registration::with('event')->where('ticket_code',strtoupper($code))->firstOrFail(); return view('tickets.complete',compact('registration')); }
 public function lookupForm(){ return view('tickets.lookup'); }
 public function lookup(Request $request){ $data=$request->validate(['ticket_code'=>['required'],'email'=>['required','email']]); $r=Registration::where('ticket_code',strtoupper($data['ticket_code']))->where('email',strtolower($data['email']))->first(); if(!$r)return back()->withInput()->withErrors(['ticket_code'=>'Ticket not found. Check your ticket code and email.']); return redirect()->route('tickets.show',$r->ticket_code); }
 public function cancel(Request $request,string $code){ $data=$request->validate(['email'=>['required','email']]); $r=Registration::where('ticket_code',strtoupper($code))->where('email',strtolower($data['email']))->first(); if(!$r)return back()->withErrors(['cancel_email'=>'Ticket not found.']); if($r->status==='checked_in')return back()->withErrors(['cancel_email'=>'A checked-in registration cannot be cancelled.']); if($r->status==='cancelled')return back()->with('success','This registration is already cancelled.'); $r->update(['status'=>'cancelled','cancelled_at'=>now()]); AuditLog::create(['action'=>'registration_cancelled','target_type'=>'Registration','target_id'=>$r->id,'ip_address'=>$request->ip()]); return back()->with('success','Your registration has been cancelled and the spot is available again.'); }
 public function spotsLeft(Event $event):int{return max(0,$event->capacity-$event->registrations()->whereIn('status',['confirmed','checked_in'])->count());}
}
